423	+/// Close the open handoff transfer calls of `plan` from its level to the end
424	+/// of the path (spec §4.7). The agent that denies the calls of a resume uses
425	+/// this, because the target of each such call does not run.
426	+///
427	+/// For each transfer call in `conversation` that has no later result, this
428	+/// puts the synthetic result `agent no longer available: {name}` directly
429	+/// after the call (`name` is the agent that the call led to). It returns the
430	+/// inserted results in path order, for the agent to emit before the denial
431	+/// results. A transfer call that already has a result is not changed.
432	+pub(crate) fn close_open_transfers(
433	+    plan: &crate::ResumePlan,
434	+    conversation: &mut Vec<Item>,
435	+) -> Vec<Item> {
436	+    let mut transfers: Vec<(String, String)> = Vec::new();
437	+    let mut level = plan.clone();
438	+    while let Some(next) = level.next_agent() {
439	+        if let Some(call_id) = level.transfer_call_to_next() {
440	+            transfers.push((call_id.to_owned(), next.to_owned()));
441	+        }
442	+        level = level.descend();
443	+    }
444	+
445	+    let mut closed = Vec::new();
446	+    for (call_id, name) in transfers {
