585	+    let session = Arc::new(MemorySession::new());
586	+    let ctx = session_ctx(&session).with_deferred_tool_calls(true);
587	+    let mut recorder = SessionRecorder::new(path[0]).with_deferral_slot(ctx.deferral_handle());
588	+    let input = AgentInput::from_user_text("hi");
589	+    recorder.record_input(&input.messages);
