591	+        .run(ctx, input)
592	+        .await
593	+        .expect("run starts")
594	+        .collect::<Vec<_>>()
595	+        .await;
596	+    assert!(
597	+        matches!(events.last(), Some(AgentEvent::RunDeferred { .. })),
598	+        "{events:?}"
