607	+/// As [`handoff_session`], but the log has no result for the transfer calls
608	+/// (`t1`, `t2`, ...). The session recorder closes them at the end of the
609	+/// run; a log from another writer can leave them open.
610	+async fn open_transfer_session(path: &[&str]) -> Arc<MemorySession> {
611	+    let recorded = handoff_session(path).await.events(None).await.unwrap();
