+    assert!(output_index(&events, "t2") < output_index(&events, "call_b"));
+    let requests = model.requests();
+    assert_eq!(requests.len(), 1, "triage's model runs next");
+    for r in &requests {
+        assert_tool_calls_paired(&r.messages);
+    }
